<?php

declare(strict_types=1);

namespace DDD\Domain\AI\Entities\Conversations;

use DDD\Domain\AI\Repo\Argus\Conversations\ArgusAIConversationSummary;
use DDD\Domain\Base\Entities\LazyLoad\LazyLoadRepo;
use DDD\Domain\Base\Entities\ValueObject;

/**
 * @property AIConversation $parent;
 * @method AIConversation getParent()
 */
#[LazyLoadRepo(LazyLoadRepo::ARGUS, repoClass: ArgusAIConversationSummary::class)]
class AIConversationSummary extends ValueObject
{
    /** @var string|null Title of the conversation (auto-generated, unless {@see $manuallyEdited}). */
    public ?string $title;

    /** @var string|null Brief summary of the conversation. */
    public ?string $text;

    /**
     * @var string|null What was DONE / decided / left open in this conversation — the episodic result line
     * the cross-session narrative and the recent-sessions tools render (`title` says the topic, `text` the course,
     * `outcome` the result). Generated alongside title/text; null on summaries from before the field existed.
     */
    public ?string $outcome;

    /**
     * @var int|null Episodic importance 1 (quick lookup) … 5 (decisions made / data written / multi-step work) —
     * generated by the summary prompt's rubric. Drives how long a finished conversation stays FINE in the
     * narrative (high importance delays its roll-up and survives as its own line inside coarser episodes). Null on
     * pre-field summaries (treated as average).
     */
    public ?int $importance;

    /**
     * @var int|null The highest message `indexInConversation` this summary covers — the STALENESS marker (the
     * compaction-anchor pattern): a conversation whose newest message index is above it needs a refresh
     * ({@see AIConversation::isDisplaySummaryStale()}), and the incremental refresh summarizes only the messages
     * past it. Stamped at generation ({@see \DDD\Domain\AI\Services\Conversations\AIConversationsService::generateAndPersistSummary()});
     * null on pre-field summaries (always stale → the next settle refreshes and stamps).
     */
    public ?int $coveredUpToMessageIndex;

    /**
     * @var bool True once the user has hand-edited the TITLE — an auto refresh then never overwrites the title again
     * (the text stays auto-refreshable). Default false. For this to survive, the summary must be PERSISTED on the
     * conversation, not regenerated every load: the Argus lazy-load ({@see ArgusAIConversationSummary::lazyload()})
     * only fires when the column is unset, and the settle/compaction refresh is gated on `!manuallyEdited`
     * ({@see AIConversation::isDisplaySummaryStale()}).
     */
    public bool $manuallyEdited = false;

    /** Record a user title edit: set the new title AND latch {@see $manuallyEdited} so future auto-refreshes skip it. */
    public function editTitleManually(string $title): void
    {
        $this->title = $title;
        $this->manuallyEdited = true;
    }
}